sim = {
  const nSub = Math.round(1 / (freq * pid.dt)), dtc = nSub * pid.dt, n = Math.round(pid.total / pid.dt);
  const f = s =&gt; scaling === "LERP" ? s : 10 * s ** 3 - 15 * s ** 4 + 6 * s ** 5;
  const ref = t =&gt; pid.q0 + (pid.q1 - pid.q0) * f(Math.min(1, Math.max(0, t / pid.moveT)));
  let q = pid.q0, qd = 0, integ = 0, ePrev = 0, u = 0;
  const out = [];
  for (let k = 0; k &lt; n; k++) {
    const t = k * pid.dt;
    if (k % nSub === 0) {
      const e = ref(t) - q;
      integ += e * dtc;
      u = Kp * e + Ki * integ + Kd * (e - ePrev) / dtc;
      ePrev = e;
    }
    const grav = gravityOn ? -pid.mass * pid.g * (pid.length / 2) * Math.cos(q) : 0;
    qd += (u - pid.friction * qd + grav) / pid.inertia * pid.dt;
    q += qd * pid.dt;
    if (!isFinite(q) || Math.abs(q) &gt; 1e3) return {rows: out, unstable: true};
    if (k % 5 === 0) out.push({t, ref: ref(t) * 180 / Math.PI, q: q * 180 / Math.PI, u});
  }
  const tail = out.filter(d =&gt; d.t &gt;= pid.total - pid.hold).map(d =&gt; d.ref - d.q);
  return {rows: out, unstable: false, mean: d3.mean(tail), swing: d3.max(tail) - d3.min(tail)};
}







